  if (typeof helpers.prepareCampaignContent === 'function') {
    const prepared = await helpers.prepareCampaignContent({ rewriteCode: __aiRewriteUsingCode, resolveFullNameFromPage: true })
    text = prepared.content.trim()
    imgs = prepared.media
